predicate IsDigit(c: char) { '0' <= c <= '9' }

// the first n characters of s are all digits
predicate {:fuel 10} AllDigitsUpTo(s: string, n: nat)
  requires n <= |s|
{
  n == 0 || (AllDigitsUpTo(s, n - 1) && IsDigit(s[n - 1]))
}

lemma NotAllDigits(s: string, i: nat, n: nat)
  requires i < n <= |s| && !IsDigit(s[i])
  ensures !AllDigitsUpTo(s, n)
  decreases n
{
  if n > i + 1 {
    NotAllDigits(s, i, n - 1);
  }
}

method allDigits(s: string) returns (result: bool)
  ensures result <==> AllDigitsUpTo(s, |s|)
{
  var i := 0;
  while i < |s|
    invariant 0 <= i <= |s|
    invariant AllDigitsUpTo(s, i)
  {
    if !IsDigit(s[i]) {
      NotAllDigits(s, i, |s|);
      return false;
    }
    i := i + 1;
  }
  return true;
}

