import icontract


def is_digit(c: str) -> bool:
    return '0' <= c <= '9'


def all_digits_up_to(s: str, n: int) -> bool:
    """The first n characters of s are all digits."""
    return all(is_digit(s[i]) for i in range(n))


@icontract.ensure(lambda s, result: result == all_digits_up_to(s, len(s)))
def allDigits(s: str) -> bool:
